import itertools
def match_offset(gi,go):
    best=[]
    H,W=len(go),len(go[0]); Gh,Gw=len(gi),len(gi[0])
    for dr in range(-Gh,H):
        for dc in range(-Gw,W):
            score=0
            for r in range(H):
                for c in range(W):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<Gh and 0<=cc<Gw:
                        expected=gi[rr][cc]; got=go[r][c]
                        if expected==got: score+=1
                    elif not expected:
                        if got==0: score+=1
            # require all zeros outside source region to be zero in target
            good=True
            for r in range(H):
                for c in range(W):
                    rr,cc=r+dr,c+dc
                    if not(0<=rr<Gh and 0<=cc<Gw):
                        if go[r][c]!=0: good=False
            if good: best.append((score,dr,dc))
    return sorted(best,key=lambda x:-x[0])[:5]
