import collections
def segs_out(out):
    # decompose output nonzeros into maximal contiguous segments (horizontal bars / vertical bars)
    cells={(r,c):out[r][c] for r in range(len(out)) for c in range(len(out[0])) if out[r][c]}
    used=set(); segs=[]
    for (r,c),v in cells.items():
        if (r,c) in used: continue
        q=collections.deque([(r,c)]); used.add((r,c)); pts=[]
        # grow: horizontal then vertical chains; simplest: collect all 4-conn same-color reachable
        while q:
            x,y=q.popleft(); pts.append((x,y))
            for dr,dc in DIRS8:
                nx,ny=x+dr,y+dc
                if (nx,ny) in cells and (nx,ny) not in used:
                    used.add((nx,ny)); q.append((nx,ny))
        segs.append(dict(col=cells[(r,c)],pts=sorted(pts)))
    return segs

def nearest_pair(seg_prev, seg_curr):
    min_=float('inf')
    best=None
    for a in seg_prev['pts']:
        for b in seg_curr['pts']:
            d=(a[0]-b[0])**2+(a[1]-b[1])**2
            if d<min_: min_=d; best=(a,b)
    return best

